class VowelCounter {
    // Функция для подсчета гласных букв в строке
    public static int CountVowels(string s) {
        string vowels = "aeiouAEIOU";
        int count = 0;

        foreach (char c in s) {
            if (vowels.Contains(c)) {
                count++;
            }
        }

        return count;
    }

    // Пример использования функции
    public static void Main() {
        Console.WriteLine(CountVowels("hello")); // Вывод: 2
        Console.WriteLine(CountVowels("sky")); // Вывод: 1
        Console.WriteLine(CountVowels("Rhythm")); // Вывод: 4
    }
}
