def max_diff(nums):
    if not nums:
        return None

    min_num = float('inf')
    max_num = -float('inf')

    for num in nums:
        if num > max_num:
            max_num = num
        elif num < min_num:
            min_num = num

    return max_num - min_num

# Пример использования
print(max_diff([1, 9, 4]))  # Выведет 8
